import { test, expect } from '@playwright/test';

test.describe('Form Auto-Save Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should auto-save the form as a draft every 30 seconds', async ({ page }) => {
    await page.fill(getByLabel('Name'), 'John Doe');
    await page.fill(getByLabel('Email'), 'john.doe@example.com');

    // Wait for 30 seconds to check for auto-save
    await page.waitForTimeout(30000);

    const draftMessage = await page.getByText('Draft saved successfully');
    expect(await draftMessage.isVisible()).toBeTruthy();
  });

  test('should retain form data after auto-save', async ({ page }) => {
    await page.fill(getByLabel('Name'), 'Jane Doe');
    await page.fill(getByLabel('Email'), 'jane.doe@example.com');

    // Wait for 30 seconds to trigger auto-save
    await page.waitForTimeout(30000);

    await page.reload();

    expect(await page.getByLabel('Name').inputValue()).toBe('Jane Doe');
    expect(await page.getByLabel('Email').inputValue()).toBe('jane.doe@example.com');
  });
});
